import sys

def bits(x):
    c = 0
    while x:
        c += x & 1
        x >>= 1
    return c

n = int(sys.stdin.read().split()[0])
a = list(range(1, n + 1))
for i in range(n):
    for j in range(n - 1 - i):
        x, y = a[j], a[j + 1]
        if bits(x) > bits(y) or (bits(x) == bits(y) and x < y):
            a[j], a[j + 1] = y, x
print(' '.join(map(str, a)))

